import { Fragment, forwardRef, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ForwardedRef } from "react";
import { Easing, Interactive, interpolate, useCurrentFrame, useVideoConfig, type InteractiveTransformProps } from "remotion";
import { createTikTokStyleCaptions, type Caption, type TikTokPage } from "@remotion/captions";

type SpeakerCaption = Caption & { speaker?: string };

interface CaptionBaseProps {
  captions: Caption[];
  combineTokensWithinMilliseconds?: number;
  holdMs?: number;
  fontSize?: number;
  fontWeight?: number;
  color?: string;
  className?: string;
}

const DEFAULT_HOLD_MS = 600;
const MIN_SILENCE_BREAK_MS = 300;

interface CaptionPageWindow {
  page: TikTokPage;
  index: number;
  speaker: string | undefined;
  startMs: number;
  speechEndMs: number;
  endMs: number;
  endsInSilence: boolean;
}

type CaptionTokenStatus = "upcoming" | "active" | "spoken";

interface CaptionTokenState {
  text: string;
  spaceBefore: boolean;
  fromMs: number;
  toMs: number;
  progress: number;
  status: CaptionTokenStatus;
}

interface CaptionPreviousPage {
  page: TikTokPage;
  pageIndex: number;
  tokens: CaptionTokenState[];
}

interface CaptionsState {
  page: TikTokPage;
  pageIndex: number;
  speaker: string | undefined;
  timeMs: number;
  activeIndex: number;
  tokens: CaptionTokenState[];
  sinceStartMs: number;
  untilEndMs: number;
  holdRoomMs: number;
  endsInSilence: boolean;
  previous: CaptionPreviousPage | null;
}

interface CaptionPagingOptions {
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}

const SENTENCE_END = /[.!?…]["')\]]*$/;

function markPageBreaks(captions: SpeakerCaption[]): Caption[] {
  return captions.map((caption, i) => {
    if (caption.pageBreakAfter !== undefined) return caption;
    const next = captions[i + 1];
    const speakerChanges =
      next !== undefined && next.speaker !== caption.speaker;
    return speakerChanges || SENTENCE_END.test(caption.text.trim())
      ? { ...caption, pageBreakAfter: true }
      : caption;
  });
}

function buildCaptionPages(
  captions: SpeakerCaption[],
  {
    combineTokensWithinMilliseconds,
    holdMs = DEFAULT_HOLD_MS,
  }: CaptionPagingOptions,
): CaptionPageWindow[] {
  if (captions.length === 0) return [];
  const { pages } = createTikTokStyleCaptions({
    captions: markPageBreaks(captions),
    combineTokensWithinMilliseconds,
    breakOnSilenceAfterMilliseconds: Math.max(holdMs, MIN_SILENCE_BREAK_MS),
  });
  const speakers = new Map<number, string | undefined>();
  for (const caption of captions) {
    if (!speakers.has(caption.startMs)) {
      speakers.set(caption.startMs, caption.speaker);
    }
  }
  const spoken = pages.filter((page) => page.tokens.length > 0);
  return spoken.map((page, index) => {
    const last = page.tokens[page.tokens.length - 1];
    const speechEndMs = last ? last.toMs : page.startMs;
    const heldUntil = speechEndMs + Math.max(0, holdMs);
    const next = spoken[index + 1];
    const endsInSilence = !next || next.startMs > heldUntil;
    const endMs = endsInSilence
      ? heldUntil
      : Math.max(page.startMs, next.startMs);
    return {
      page,
      index,
      speaker: speakers.get(page.tokens[0].fromMs),
      startMs: page.startMs,
      speechEndMs,
      endMs,
      endsInSilence,
    };
  });
}

function findWindowIndex(windows: CaptionPageWindow[], timeMs: number): number {
  let lo = 0;
  let hi = windows.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (windows[mid].startMs <= timeMs) {
      found = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (found === -1) return -1;
  return timeMs < windows[found].endMs ? found : -1;
}

function tokenProgress(fromMs: number, toMs: number, timeMs: number): number {
  if (timeMs < fromMs) return 0;
  if (toMs <= fromMs) return 1;
  return Math.min(1, (timeMs - fromMs) / (toMs - fromMs));
}

function getTokenStates(
  page: TikTokPage,
  timeMs: number,
): { activeIndex: number; tokens: CaptionTokenState[] } {
  let activeIndex = -1;
  page.tokens.forEach((token, i) => {
    if (token.fromMs <= timeMs) activeIndex = i;
  });
  const tokens = page.tokens.map(
    (token, i): CaptionTokenState => ({
      text: token.text.trim(),
      spaceBefore: i > 0 && /^\s/.test(token.text),
      fromMs: token.fromMs,
      toMs: token.toMs,
      progress: tokenProgress(token.fromMs, token.toMs, timeMs),
      status:
        i < activeIndex ? "spoken" : i === activeIndex ? "active" : "upcoming",
    }),
  );
  return { activeIndex, tokens };
}

function getCaptionsState(
  windows: CaptionPageWindow[],
  timeMs: number,
): CaptionsState | null {
  const found = findWindowIndex(windows, timeMs);
  if (found === -1) return null;
  const window = windows[found];
  const { activeIndex, tokens } = getTokenStates(window.page, timeMs);
  const before = found > 0 ? windows[found - 1] : null;
  const previous =
    before && !before.endsInSilence
      ? {
          page: before.page,
          pageIndex: before.index,
          tokens: getTokenStates(before.page, before.endMs).tokens,
        }
      : null;
  return {
    page: window.page,
    pageIndex: window.index,
    speaker: window.speaker,
    timeMs,
    activeIndex,
    tokens,
    sinceStartMs: timeMs - window.startMs,
    untilEndMs: window.endMs - timeMs,
    holdRoomMs: window.endMs - window.speechEndMs,
    endsInSilence: window.endsInSilence,
    previous,
  };
}

function getExitWindowMs(state: CaptionsState, exitMs: number): number {
  return Math.max(1, Math.min(exitMs, state.holdRoomMs));
}

function groupCaptionWords(
  tokens: CaptionTokenState[],
): { index: number; token: CaptionTokenState }[][] {
  const words: { index: number; token: CaptionTokenState }[][] = [];
  tokens.forEach((token, index) => {
    const current = words[words.length - 1];
    if (!current || token.spaceBefore) {
      words.push([{ index, token }]);
    } else {
      current.push({ index, token });
    }
  });
  return words;
}

function normalizeCaptionWord(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[^\p{L}\p{N}']/gu, "");
}

function createKeywordMatcher(
  keywords: readonly string[] = [],
): (text: string) => boolean {
  const set = new Set(keywords.map(normalizeCaptionWord).filter(Boolean));
  return (text) => set.has(normalizeCaptionWord(text));
}

function captionWordText(word: { token: CaptionTokenState }[]): string {
  return word.map(({ token }) => token.text).join("");
}

interface CaptionWordRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

function sameRects(a: CaptionWordRect[], b: CaptionWordRect[]): boolean {
  return (
    a.length === b.length &&
    a.every(
      (r, i) =>
        r.left === b[i].left &&
        r.top === b[i].top &&
        r.width === b[i].width &&
        r.height === b[i].height,
    )
  );
}

function useCaptionWordRects(
  pageIndex: number,
  count: number,
): {
  wordRef: (index: number) => (el: HTMLElement | null) => void;
  rects: CaptionWordRect[] | null;
} {
  const elements = useRef<(HTMLElement | null)[]>([]);
  const [measured, setMeasured] = useState<{
    pageIndex: number;
    rects: CaptionWordRect[];
  } | null>(null);

  useLayoutEffect(() => {
    if (pageIndex === -1) return;
    const rects = elements.current.slice(0, count).map((el) =>
      el
        ? {
            left: el.offsetLeft,
            top: el.offsetTop,
            width: el.offsetWidth,
            height: el.offsetHeight,
          }
        : { left: 0, top: 0, width: 0, height: 0 },
    );
    setMeasured((prev) =>
      prev && prev.pageIndex === pageIndex && sameRects(prev.rects, rects)
        ? prev
        : { pageIndex, rects },
    );
  });

  return {
    wordRef: (index) => (el) => {
      elements.current[index] = el;
    },
    rects: measured && measured.pageIndex === pageIndex ? measured.rects : null,
  };
}

function useCaptions({
  captions,
  combineTokensWithinMilliseconds,
  holdMs = DEFAULT_HOLD_MS,
}: {
  captions: SpeakerCaption[];
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}): CaptionsState | null {
  const frame = useSceneFrame();
  const { fps } = useSceneConfig();
  const windows = useMemo(
    () =>
      buildCaptionPages(captions, { combineTokensWithinMilliseconds, holdMs }),
    [captions, combineTokensWithinMilliseconds, holdMs],
  );
  return getCaptionsState(windows, (frame / fps) * 1000);
}

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

export interface CaptionLabelMakerProps extends CaptionBaseProps {
  tapeColor?: string;
}

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const PRESS_MS = 50;
const PRESS_SCALE = 0.92;
const TILT_DEG = -1.5;
const PAD_Y = 0.16;
const LEAD_EM = 0.42;
const RADIUS = 0.16;
const EMBOSS = "0 1px 0 rgba(0, 0, 0, 0.55)";
const RELIEF =
  "inset 0 1px 0 rgba(255, 255, 255, 0.14), inset 0 -1px 0 rgba(0, 0, 0, 0.5)";

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function revealedCount(
  count: number,
  fromMs: number,
  toMs: number,
  timeMs: number,
): number {
  if (timeMs < fromMs) return 0;
  const duration = Math.max(toMs - fromMs, 1);
  return Math.min(
    count,
    Math.floor(((timeMs - fromMs) / duration) * count) + 1,
  );
}

function CaptionLabelMakerContent(
  {
    captions,
    combineTokensWithinMilliseconds = 1000,
    holdMs = DEFAULT_HOLD_MS,
    fontSize = 64,
    fontWeight = 800,
    color = "#ffffff",
    tapeColor = "#18181b",
    className,
    style,
  }: CaptionLabelMakerProps & InteractiveTransformProps,
  ref: ForwardedRef<HTMLDivElement>,
) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return <div ref={ref} style={style} />;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    { ...clamp, easing: enterEasing },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  const segment: CSSProperties = {
    display: "inline-block",
    verticalAlign: "top",
    background: tapeColor,
    paddingBlock: `${PAD_Y}em`,
    paddingRight: 1,
    marginRight: -1,
    boxShadow: RELIEF,
  };

  const words = groupCaptionWords(state.tokens).map((word) => {
    const chars = Array.from(captionWordText(word));
    const fromMs = word[0].token.fromMs;
    const toMs = word[word.length - 1].token.toMs;
    return {
      key: `${state.pageIndex}-${word[0].index}`,
      chars,
      fromMs,
      toMs,
      revealed: revealedCount(chars.length, fromMs, toMs, state.timeMs),
    };
  });
  const last = words[words.length - 1];
  const finished = last !== undefined && last.revealed === last.chars.length;

  return (
    <div ref={ref} style={style}>
      <div
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          lineHeight: 1.1,
          textAlign: "center",
          opacity: Math.min(enter, exit),
          transform: `translateY(${(1 - enter) * RISE_EM}em)`,
        }}
      >
        <span
          style={{
            display: "inline-block",
            whiteSpace: "nowrap",
            transform: `rotate(${TILT_DEG}deg)`,
            filter: "drop-shadow(0 2px 4px rgba(0, 0, 0, 0.35))",
          }}
        >
          <span
            style={{
              ...segment,
              width: `${LEAD_EM}em`,
              borderRadius: `${RADIUS}em 0 0 ${RADIUS}em`,
            }}
          >
            {"\u00a0"}
          </span>
          {words.map((word, w) => {
            const duration = Math.max(word.toMs - word.fromMs, 1);
            return (
              <Fragment key={word.key}>
                {w > 0 && (
                  <span
                    style={{
                      ...segment,
                      visibility: word.revealed > 0 ? "visible" : "hidden",
                    }}
                  >
                    {"\u00a0"}
                  </span>
                )}
                {word.chars.map((char, c) => {
                  const pressedAt =
                    word.fromMs + (c / word.chars.length) * duration;
                  const press = interpolate(
                    state.timeMs - pressedAt,
                    [0, PRESS_MS],
                    [PRESS_SCALE, 1],
                    clamp,
                  );
                  return (
                    <span
                      key={c}
                      style={{
                        ...segment,
                        visibility: c < word.revealed ? "visible" : "hidden",
                      }}
                    >
                      <span
                        style={{
                          display: "inline-block",
                          transform: `scale(${press})`,
                          textShadow: EMBOSS,
                        }}
                      >
                        {char}
                      </span>
                    </span>
                  );
                })}
              </Fragment>
            );
          })}
          <span
            style={{
              ...segment,
              width: `${LEAD_EM}em`,
              borderRadius: `0 ${RADIUS}em ${RADIUS}em 0`,
              visibility: finished ? "visible" : "hidden",
            }}
          >
            {"\u00a0"}
          </span>
        </span>
      </div>
    </div>
  );
}

export const CaptionLabelMaker = Interactive.create({
  Component: forwardRef(CaptionLabelMakerContent),
  componentName: "<CaptionLabelMaker>",
  layout: "none",
  schema: Interactive.captionsSchema,
});
